addEventListener('fetch', event => {
  // Simple Cloudflare Worker example: early drop of suspicious requests
  // (Production: use durable objects/kv or Cloudflare Rate Limiting + WAF)
  event.respondWith(handle(event.request))
})

async function handle(request) {
  // Cheap heuristics first: block requests missing expected headers
  const ua = request.headers.get('user-agent') || ''
  if (!ua || ua.length < 8) {
    return new Response('Too many requests', { status: 429 })
  }

  // Example: challenge requests with suspicious URI pattern
  const url = new URL(request.url)
  if (url.pathname.startsWith('/.well-known/') && Math.random() < 0.01) {
    // In practice, use challenge APIs / WAF rules to verify human clients
    return new Response('Challenge required', { status: 403 })
  }

  // Otherwise, proxy to origin / cache
  return fetch(request)
}
